package com.gameaggregator.incidentservice.domain;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="incidents") public class Incident{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true)public String incidentNumber;@Column(nullable=false)public String title;@Lob @Column(nullable=false)public String description;@Column(nullable=false)public String severity;@Column(nullable=false)public String status="OPEN";public UUID assigneeId;public UUID relatedDeploymentId;@Column(nullable=false)public Instant createdAt=Instant.now();public Instant acknowledgedAt;public Instant resolvedAt;@Lob public String postmortem;@Version public long revision;protected Incident(){}public Incident(String n,String t,String d,String s,UUID a,UUID r){incidentNumber=n;title=t;description=d;severity=s;assigneeId=a;relatedDeploymentId=r;}}